(6947993, 1046736, 30712, '<td valign="top">Cool lighting and great impact.</td>', 'Cool lighting and great impact.', '2013-01-03 10:10:45.000000', NULL, 1),
(6947997, 1046711, 101256, '<td valign="top">Cute and very clever. Nice use of aperture to create depth. Crisp, sharp with no obvious edges from the combination - excellent concept.  I like it</td>', 'Cute and very clever. Nice use of aperture to create depth. Crisp, sharp with no obvious edges from the combination - excellent concept.  I like it', '2013-01-03 10:13:33.000000', NULL, 1),
(6948022, 1046705, 101256, '<td valign="top">Interesting to say the least. Cool colors in the middle of the color range are always tough to deal with. Can''t say I like the theme, but that''s a minor consideration. Nothing overt to complain about.</td>', 'Interesting to say the least. Cool colors in the middle of the color range are always tough to deal with. Can''t say I like the theme, but that''s a minor consideration. Nothing overt to complain about.', '2013-01-03 10:44:12.000000', NULL, 1),
(6948024, 1046608, 101256, '<td valign="top">Has an interesting tintype feel to the image - not sure if that was intentional or not.  Birds are too far away to be of interest - overall not a great image.</td>', 'Has an interesting tintype feel to the image - not sure if that was intentional or not.  Birds are too far away to be of interest - overall not a great image.', '2013-01-03 10:45:23.000000', NULL, 1),
(6948027, 1046737, 101256, '<td valign="top">I like the idea, the execution of the idea fails. The vines are much too dark to be effective against the lighter blue. It might have been an interesting experiment to reverse the image and see what that looked like.</td>', 'I like the idea, the execution of the idea fails. The vines are much too dark to be effective against the lighter blue. It might have been an interesting experiment to reverse the image and see what that looked like.', '2013-01-03 10:47:02.000000', NULL, 1);
